// TH18 v1.00a Stage 4 w10: st04.ecl.txt MainSub07:1028-1035, GirlD02:580-736.
// Shell: control enemy at (0,0), invulnerable and body-contact off; the three
// source girls keep their source hit/hurt boxes and source coordinates.

const TIME_LIMIT: int = 1410; // 120 buffer + 890 source window + 400 tail
const SOURCE_LIMIT: int = 890; // MainSub07 entry .. main enmKillAll/etClear
const TH18_RICE: int = 480; // source etSprite type 8

// Source GirlD02_at / _at2: etEx type 8, a=120, s=+/-0.0052359877 rad/frame
// (~55 BAM/frame), then the finite effect ends.
xformdef SPIN(dir: int) {
    @120 set_ang_vel((55 * dir) as angle);
    set_ang_vel(0deg);
}

// Source GirlD02_at: color 4 / et0 (+); GirlD02_at2: color 2 / et1 (-).
async sub girl_shooter(color: int, dir: int) {
    var rank: int = global(GVAR_RANK);
    var n: int = 10;          // !E
    var speed: fx = 1fx;
    var delay: int = 60;
    var period: int = 120;
    var dist: fx = 12fx;      // etDist 16 minus ANIM a=1 retreat 4*speed
    if rank == 1 { n = 45; }  // !N
    if rank == 2 { n = 60; speed = 1.5fx; delay = 50; period = 100; dist = 10fx; } // !H
    if rank == 3 { n = 70; speed = 1.5fx; delay = 45; period = 90; dist = 10fx; }  // !LO
    sh_reset(0);
    sh_sprite(0, TH18_RICE, color);
    sh_ring(0, 1);
    sh_aim(0, 0);            // source mode 2; a complete ring makes aim irrelevant
    sh_count(0, n, 1);
    sh_speed(0, speed, 0fx); // etSpeed first endpoint, single layer
    sh_dist(0, dist);
    sh_xform(0, SPIN(dir));
    wait(delay);
    for i in 0..30 {         // source $B = 30
        sh_angle(0, rand(65536) as angle, 0deg); // source RANDRAD per wave
        sh_fire(0);
        wait(period);
    }
}

// Source GirlD02:580-736. Stage-relative coordinates; parent FINAL is (0,0).
async sub girl_d02() {
    set_invuln(65535);       // invincible practice shell
    set_hurtbox(16fx);       // source setHurtbox(32,32)
    set_hitbox(12fx);        // source setHitbox(24,24)
    move_vel(0, 90deg, 3fx, EASE_LINEAR);         // moveVel(pi/2, 3.0)
    move_speed(80, 0fx, EASE_QUAD_IN);            // moveVelTime(80, mode 1, pi/2, 0)
    wait(80);
    spawn girl_shooter(4, 1);
    spawn girl_shooter(2, -1);
    move_speed(80, 0fx, EASE_QUAD_IN);            // source second 80-frame 0->0 write
    wait(500);
    move_speed(80, -1.4fx, EASE_QUAD_IN);         // moveVelTime(80, mode 1, pi/2, -1.4)
    loop { wait(1000); }
}

// Source MainSub07: center at local 0, sides at local 30; MainLatter then
// waits 300+560 before the stage-level enmKillAll/etClear at local 890.
async sub pattern() {
    wait(120);               // required opening buffer
    _ = spawn_enemy(0fx, -32fx, 2700, 0, 0, 0, girl_d02);
    wait(30);
    _ = spawn_enemy(-120fx, -32fx, 2700, 0, 0, 0, girl_d02);
    _ = spawn_enemy(120fx, -32fx, 2700, 0, 0, 0, girl_d02);
    wait(SOURCE_LIMIT - 30); // 860
    kill_all_enemies(KILL_SILENT); // source enmKillAll at local 890
    loop { wait(1); }
}

async sub boss_main() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, boss_main);
    loop { wait(600); }
}
